"use strict";(self.webpackChunkchatgpt_iel=self.webpackChunkchatgpt_iel||[]).push([[4118],{3413:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"ONDG1":[{"type":"link","label":"Apresenta\xe7\xe3o","href":"/ChatGPT-IEL/docs/","docId":"apresentacao","unlisted":false},{"type":"category","label":"CURIOSO","items":[{"type":"link","label":"Login (Gr\xe1tis, Plus e Pro)","href":"/ChatGPT-IEL/docs/curioso/login/uso_pessoal","docId":"curioso/login/uso_pessoal","unlisted":false},{"type":"link","label":"Login (Team/Business)","href":"/ChatGPT-IEL/docs/curioso/login/uso_team","docId":"curioso/login/uso_team","unlisted":false},{"type":"link","label":"Primeiros exemplos","href":"/ChatGPT-IEL/docs/curioso/primeiros_exemplos","docId":"curioso/primeiros_exemplos","unlisted":false},{"type":"link","label":"Por que ChatGPT?","href":"/ChatGPT-IEL/docs/curioso/porqueChatGPT","docId":"curioso/porqueChatGPT","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/ChatGPT-IEL/docs/curioso/curioso-abertura"},{"type":"category","label":"INICIA\xc7\xc3O","items":[{"type":"category","label":"Vocabul\xe1rio","items":[{"type":"link","label":"O professor GPT","href":"/ChatGPT-IEL/docs/iniciacao/vocabulario","docId":"iniciacao/vocabulario","unlisted":false},{"type":"link","label":"ChatGPT","href":"/ChatGPT-IEL/docs/iniciacao/chatgpt","docId":"iniciacao/chatgpt","unlisted":false},{"type":"link","label":"LLM","href":"/ChatGPT-IEL/docs/iniciacao/LLM","docId":"iniciacao/LLM","unlisted":false},{"type":"link","label":"Prompt","href":"/ChatGPT-IEL/docs/iniciacao/prompts","docId":"iniciacao/prompts","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Ferramentas do ChatGPT","href":"/ChatGPT-IEL/docs/iniciacao/ferramentas","docId":"iniciacao/ferramentas","unlisted":false},{"type":"link","label":"Modo Agente","href":"/ChatGPT-IEL/docs/iniciacao/modo-agente","docId":"iniciacao/modo-agente","unlisted":false},{"type":"link","label":"Limites de Uso","href":"/ChatGPT-IEL/docs/iniciacao/limites-uso","docId":"iniciacao/limites-uso","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/ChatGPT-IEL/docs/iniciacao/iniciacao-abertura"},{"type":"category","label":"EXPLORADOR","items":[{"type":"link","label":"Desmistificando o ChatGPT","href":"/ChatGPT-IEL/docs/explorador/desmistificando","docId":"explorador/desmistificando","unlisted":false},{"type":"link","label":"Criatividade","href":"/ChatGPT-IEL/docs/explorador/criatividade","docId":"explorador/criatividade","unlisted":false},{"type":"link","label":"Alucina\xe7\xf5es","href":"/ChatGPT-IEL/docs/explorador/alucinacao","docId":"explorador/alucinacao","unlisted":false},{"type":"link","label":"O vi\xe9s","href":"/ChatGPT-IEL/docs/explorador/vies","docId":"explorador/vies","unlisted":false},{"type":"link","label":"Privacidade","href":"/ChatGPT-IEL/docs/explorador/privacidade","docId":"explorador/privacidade","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"CONSTRUTOR","items":[{"type":"link","label":"Estrutura do prompt","href":"/ChatGPT-IEL/docs/construtor/prompt","docId":"construtor/prompt","unlisted":false},{"type":"link","label":"Dicas","href":"/ChatGPT-IEL/docs/construtor/prompt-dicas","docId":"construtor/prompt-dicas","unlisted":false},{"type":"link","label":"O Or\xe1culo","href":"/ChatGPT-IEL/docs/construtor/oraculo/","docId":"construtor/oraculo/index","unlisted":false},{"type":"link","label":"Escolhendo um Modelo","href":"/ChatGPT-IEL/docs/construtor/modelos/","docId":"construtor/modelos/modelos","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"CRIADOR","items":[{"type":"link","label":"Detetive ChatGPT","href":"/ChatGPT-IEL/docs/criador/detetive","docId":"criador/detetive","unlisted":false},{"type":"link","label":"O poder das palavras certas","href":"/ChatGPT-IEL/docs/criador/vocabulario","docId":"criador/vocabulario","unlisted":false},{"type":"link","label":"Mem\xf3ria de peixe ou elefante?","href":"/ChatGPT-IEL/docs/criador/peixe-ou-elefante","docId":"criador/peixe-ou-elefante","unlisted":false},{"type":"link","label":"Novo assunto? Nova conversa!","href":"/ChatGPT-IEL/docs/criador/mudando-assunto","docId":"criador/mudando-assunto","unlisted":false},{"type":"link","label":"Projetos","href":"/ChatGPT-IEL/docs/criador/projetos","docId":"criador/projetos","unlisted":false},{"type":"category","label":"GPTs","items":[{"type":"link","label":"Construindo GPTs","href":"/ChatGPT-IEL/docs/criador/GPTs/","docId":"criador/GPTs/GPTs","unlisted":false},{"type":"link","label":"GPT personalizado","href":"/ChatGPT-IEL/docs/criador/GPTs/Ferramenta","docId":"criador/GPTs/Ferramenta","unlisted":false},{"type":"link","label":"Exemplo","href":"/ChatGPT-IEL/docs/criador/GPTs/Exemplos","docId":"criador/GPTs/Exemplos","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true}]},"docs":{"apresentacao":{"id":"apresentacao","title":"Apresenta\xe7\xe3o","description":"Parab\xe9ns por iniciar sua jornada no GPT Estrat\xe9gico: domine o uso estrat\xe9gico do ChatGPT no ambiente corporativo! O simples fato de estar aqui j\xe1 demonstra sua curiosidade e disposi\xe7\xe3o para explorar o fascinante mundo da intelig\xeancia artificial. Este \xe9 o primeiro passo para transformar a maneira como voc\xea pensa e trabalha com o ChatGPT.","sidebar":"ONDG1"},"construtor/construtor-abertura":{"id":"construtor/construtor-abertura","title":"construtor-abertura","description":""},"construtor/modelos/modelos":{"id":"construtor/modelos/modelos","title":"modelos","description":"Se voc\xea usa o ChatGPT e tem acesso \xe0 vers\xe3o paga (Plus, Pro, Team/Business ou Enterprise), encontrar\xe1 hoje duas op\xe7\xf5es principais de modelos: o GPT-5 (com os modos Auto, Instant e Thinking) e o GPT-4o, dispon\xedvel como alternativa. Esta se\xe7\xe3o descreve como cada um funciona e em quais situa\xe7\xf5es pode ser utilizado.","sidebar":"ONDG1"},"construtor/oraculo/index":{"id":"construtor/oraculo/index","title":"O Or\xe1culo","description":"Como vimos anteriormente, a chave para obter as melhores respostas do ChatGPT \xe9 aprender a formular boas perguntas, ou prompts. Pense no ChatGPT como um chef de cozinha voc\xea n\xe3o precisa elaborar esses prompts sozinho. O ChatGPT pode ser um \xf3timo parceiro, ajudando voc\xea a melhorar suas perguntas com base nos par\xe2metros que ele j\xe1 conhece.","sidebar":"ONDG1"},"construtor/prompt":{"id":"construtor/prompt","title":"Estrutura do prompt","description":"J\xe1 aconteceu de voc\xea fazer uma pergunta a algu\xe9m e receber uma resposta que n\xe3o correspondia exatamente ao que voc\xea desejava saber? Com o ChatGPT, o mesmo pode acontecer. A maneira como voc\xea formula sua pergunta impacta diretamente a qualidade da resposta que voc\xea receber\xe1.","sidebar":"ONDG1"},"construtor/prompt-dicas":{"id":"construtor/prompt-dicas","title":"Dicas","description":"Algumas dicas para a constru\xe7\xe3o de prompts.","sidebar":"ONDG1"},"criador/criador-abertura":{"id":"criador/criador-abertura","title":"criador-abertura","description":""},"criador/detetive":{"id":"criador/detetive","title":"Detetive ChatGPT","description":"Lembra das sugest\xf5es que abordamos quando falamos sobre como estruturar um prompt? Quero retomar o assunto mas agora com uma abordagem diferente. Vou usar uma met\xe1fora que vai te ajudar a entender o que \xe9 um prompt e como escrev\xea-lo de forma eficaz.","sidebar":"ONDG1"},"criador/GPTs/Exemplos":{"id":"criador/GPTs/Exemplos","title":"Exemplo","description":"No in\xedcio do curso realizamos uma atividade de \u201cquebra-gelo\u201d em que cada participante usou o ChatGPT para produzir um texto de apresenta\xe7\xe3o pessoal. Vamos retomar esse exemplo e analisar o que mudaria caso quis\xe9ssemos transformar aquele prompt inicial em um GPT personalizado.","sidebar":"ONDG1"},"criador/GPTs/Ferramenta":{"id":"criador/GPTs/Ferramenta","title":"GPT personalizado","description":"Um GPT customizado (ou Custom GPT) \xe9 uma vers\xe3o personalizada do ChatGPT que voc\xea cria para desempenhar tarefas espec\xedficas, com instru\xe7\xf5es, conhecimentos e capacidades adaptados \xe0s suas necessidades.","sidebar":"ONDG1"},"criador/GPTs/GPTs":{"id":"criador/GPTs/GPTs","title":"Construindo GPTs","description":"Chegou a hora de colocar a m\xe3o na massa na constru\xe7\xe3o de GPTs personalizados. Vamos interagir com a ferramenta de constru\xe7\xe3o de GPTs para configurar comportamentos, anexar documentos e transformar tudo isso em solu\xe7\xf5es que podem ser usadas por equipes inteiras.","sidebar":"ONDG1"},"criador/mudando-assunto":{"id":"criador/mudando-assunto","title":"Novo assunto? Nova conversa!","description":"Quando falei sobre a estrutura conversacional do ChatGPT, expliquei que ele mant\xe9m o contexto da conversa para proporcionar respostas mais coerentes. Relembrando:","sidebar":"ONDG1"},"criador/peixe-ou-elefante":{"id":"criador/peixe-ou-elefante","title":"Mem\xf3ria de peixe ou elefante?","description":"\xc9 comum associar a \\"mem\xf3ria curta\\" ao peixinho-dourado (ou goldfish). Embora seja um mito popular que esses peixes t\xeam uma mem\xf3ria de apenas alguns segundos, a verdade \xe9 que eles conseguem se lembrar de informa\xe7\xf5es por meses.","sidebar":"ONDG1"},"criador/projetos":{"id":"criador/projetos","title":"Projetos","description":"Imagine que voc\xea est\xe1 organizando uma s\xe9rie de tarefas para um cliente ou um trabalho de longo prazo \u2014 por exemplo, planejar um lan\xe7amento de produto ou desenvolver uma pesquisa para a faculdade. Muitas vezes, h\xe1 v\xe1rias conversas, documentos de refer\xeancia, arquivos diversos (planilhas, PDFs, imagens) e instru\xe7\xf5es espec\xedficas de como voc\xea deseja que tudo seja feito.","sidebar":"ONDG1"},"criador/vocabulario":{"id":"criador/vocabulario","title":"Exemplos","description":"Voc\xea j\xe1 passou por aquela situa\xe7\xe3o em que sabe que est\xe1 prestes a lembrar de algo, mas falta uma \xfanica palavra para que a mem\xf3ria se complete? Esse fen\xf4meno \xe9 conhecido como o \\"efeito de ponta da l\xedngua\\". Tudo est\xe1 ali, na sua mente, mas a palavra certa ainda n\xe3o veio. No momento em que ela aparece, \xe9 como se o bloqueio se desfizesse, e tudo o que voc\xea estava tentando lembrar flui naturalmente.","sidebar":"ONDG1"},"curioso/chat-curitiba":{"id":"curioso/chat-curitiba","title":"chat-curitiba","description":"Oi. Tudo bem?"},"curioso/chat-curitiba-continua":{"id":"curioso/chat-curitiba-continua","title":"chat-curitiba-continua","description":"Sobre o que estamos conversando?"},"curioso/curioso-abertura":{"id":"curioso/curioso-abertura","title":"curioso-abertura","description":"Seja bem-vindo ao cap\xedtulo Curioso. Aqui, quero te acompanhar nos seus primeiros passos com o ChatGPT. Vamos come\xe7ar pelo b\xe1sico: como fazer login. Vou te mostrar como acessar a plataforma usando uma conta pessoal (Gr\xe1tis, Plus ou Pro) e tamb\xe9m como funciona o processo na vers\xe3o corporativa (Team/Business), incluindo cria\xe7\xe3o de conta, convites e SSO.","sidebar":"ONDG1"},"curioso/login/uso_pessoal":{"id":"curioso/login/uso_pessoal","title":"Login - uso pessoal","description":"Vers\xe3o Gr\xe1tis, Plus e Pro.","sidebar":"ONDG1"},"curioso/login/uso_team":{"id":"curioso/login/uso_team","title":"Login - vers\xe3o corporativa","description":"Vers\xe3o Team/Business.","sidebar":"ONDG1"},"curioso/porqueChatGPT":{"id":"curioso/porqueChatGPT","title":"Por que ChatGPT?","description":"O nome ChatGPT n\xe3o foi escolhido por acaso. Ele reflete a forma de intera\xe7\xe3o com essa ferramenta: uma conversa din\xe2mica e cont\xednua. Entender como essa estrutura de chat funciona \xe9 essencial para tirar o m\xe1ximo proveito da ferramenta, garantindo que a comunica\xe7\xe3o flua e gere as respostas que voc\xea realmente busca.","sidebar":"ONDG1"},"curioso/primeiros_exemplos":{"id":"curioso/primeiros_exemplos","title":"Exemplos","description":"Neste t\xf3pico, me propus um desafio quero que voc\xea j\xe1 saia aplicando o que aprendeu no seu dia a dia profissional.","sidebar":"ONDG1"},"explorador/alucinacao":{"id":"explorador/alucinacao","title":"Alucina\xe7\xf5es","description":"Este conte\xfado est\xe1 presente no guia Desmistificando a Intelig\xeancia Artificial.","sidebar":"ONDG1"},"explorador/criatividade":{"id":"explorador/criatividade","title":"Criatividade","description":"Na se\xe7\xe3o \\"Desmistificando o ChatGPT\\", vimos que o ChatGPT \xe9 treinado com uma enorme quantidade de dados textuais para prever a pr\xf3xima palavra em uma frase, considerando o contexto fornecido.","sidebar":"ONDG1"},"explorador/desmistificando":{"id":"explorador/desmistificando","title":"Desmistificando o ChatGPT","description":"Desmistificar algo significa retirar a camada de complexidade ou mist\xe9rio que o torna dif\xedcil de entender. Quando falo em desmistificar o ChatGPT, meu objetivo \xe9 remover o mist\xe9rio e a complexidade em torno da tecnologia. Assim, estou simplificando e esclarecendo seu funcionamento para que qualquer pessoa, independentemente do seu n\xedvel de conhecimento t\xe9cnico, possa compreend\xea-lo e utiliz\xe1-lo com propriedade.","sidebar":"ONDG1"},"explorador/exemplo problema acuracidade":{"id":"explorador/exemplo problema acuracidade","title":"exemplo problema acuracidade","description":"Neste gemini tem um exemplo de erro que foi arrumado pela \\"acuracidade\\""},"explorador/explorador-abertura":{"id":"explorador/explorador-abertura","title":"explorador-abertura","description":"Explorador"},"explorador/privacidade":{"id":"explorador/privacidade","title":"Privacidade","description":"\xc9 fundamental entender que o ChatGPT pode utilizar os dados que voc\xea compartilha para aprimorar seus modelos. Embora existam op\xe7\xf5es de controle de privacidade, \xe9 essencfial estar atento ao tipo de informa\xe7\xe3o enviada durante as conversas. Compartilhar dados confidenciais pode representar riscos, especialmente se esses dados forem integrados inadvertidamente ao processo de treinamento do modelo.","sidebar":"ONDG1"},"explorador/vies":{"id":"explorador/vies","title":"O vi\xe9s","description":"J\xe1 escrevi neste guia que o ChatGPT foi treinado com uma vasta quantidade de textos da internet, incluindo livros, artigos, not\xedcias, sites e f\xf3runs. Durante esse processo, ele \\"aprendeu\\" analisando bilh\xf5es de exemplos de como as pessoas se comunicam. Esses exemplos foram criados por pessoas de diferentes partes do mundo, o que \xe9 positivo, pois oferece uma diversidade de informa\xe7\xf5es. Por\xe9m, \xe9 aqui que surge um desafio.","sidebar":"ONDG1"},"iniciacao/chatgpt":{"id":"iniciacao/chatgpt","title":"O que \xe9 o ChatGPT?","description":"Imagine que voc\xea pudesse conversar com um assistente inteligente que entende o que voc\xea escreve e responde de forma clara, r\xe1pida e \xfatil. \xc9 isso que o ChatGPT faz. Ele \xe9 uma ferramenta digital que funciona como um tipo de \u201cajudante virtual\u201d. Voc\xea digita uma pergunta, uma ideia ou at\xe9 um pedido, e ele responde com base em tudo o que aprendeu \u2014 e, quando necess\xe1rio, pode at\xe9 buscar informa\xe7\xf5es mais recentes na internet.","sidebar":"ONDG1"},"iniciacao/ferramentas":{"id":"iniciacao/ferramentas","title":"Ferramentas do ChatGPT","description":"Imagine o ChatGPT como uma caixa de ferramentas inteligente. Vamos falar de algumas delas:","sidebar":"ONDG1"},"iniciacao/iniciacao-abertura":{"id":"iniciacao/iniciacao-abertura","title":"iniciacao-abertura","description":"Bem-vindo ao cap\xedtulo de \\"inicia\xe7\xe3o\\" deste guia sobre o ChatGPT!","sidebar":"ONDG1"},"iniciacao/limites-uso":{"id":"iniciacao/limites-uso","title":"Limites de Uso","description":"Atualmente, n\xe3o existe um painel centralizado que mostre, de forma clara, quanto da sua cota de uso j\xe1 foi consumido nos diferentes recursos do ChatGPT. Algumas informa\xe7\xf5es aparecem no pr\xf3prio menu de ferramentas, por exemplo, ao clicar em Ferramentas e passar o mouse sobre recursos como Investigar ou Modo Agente, \xe9 poss\xedvel visualizar breves descri\xe7\xf5es sobre limites de uso. No entanto, para muitos outros recursos, n\xe3o h\xe1 qualquer indica\xe7\xe3o direta de consumo dispon\xedvel ao usu\xe1rio.","sidebar":"ONDG1"},"iniciacao/LLM":{"id":"iniciacao/LLM","title":"O que \xe9 um LLM?","description":"LLM \xe9 a sigla para \\"Modelo de Linguagem Grande\\" (do ingl\xeas Large Language Model). Imagine que voc\xea est\xe1 conversando com algu\xe9m que leu milhares de livros, jornais, artigos e textos variados. Essa pessoa teria uma capacidade enorme de compreender perguntas, criar hist\xf3rias, explicar assuntos complicados ou at\xe9 sugerir solu\xe7\xf5es para problemas. \xc9 exatamente assim que funciona um LLM: ele \xe9 como um grande leitor que estudou um volume gigantesco de informa\xe7\xf5es, permitindo que entenda e produza textos muito parecidos com os escritos por humanos.","sidebar":"ONDG1"},"iniciacao/modo-agente":{"id":"iniciacao/modo-agente","title":"Modo Agente","description":"Imagine poder contar com um assistente digital que n\xe3o apenas entende o que voc\xea quer, mas tamb\xe9m \xe9 capaz de planejar e executar as tarefas por conta pr\xf3pria, como se fosse um profissional digital que trabalha ao seu lado. Essa \xe9 a proposta do Modo Agente do ChatGPT.","sidebar":"ONDG1"},"iniciacao/prompts":{"id":"iniciacao/prompts","title":"O que \xe9 um *Prompt* no ChatGPT","description":"Imagine que voc\xea est\xe1 conversando com algu\xe9m que pode responder qualquer pergunta ou realizar uma tarefa que voc\xea pedir. No entanto, essa pessoa s\xf3 vai agir ou falar algo se voc\xea fizer uma pergunta clara ou explicar exatamente o que voc\xea quer. No contexto do ChatGPT, essa pergunta ou instru\xe7\xe3o que voc\xea escreve \xe9 chamada de prompt. \xc9 como dar instru\xe7\xf5es para algu\xe9m fazer algo por voc\xea, s\xf3 que, neste caso, voc\xea est\xe1 falando com uma intelig\xeancia artificial.","sidebar":"ONDG1"},"iniciacao/vocabulario":{"id":"iniciacao/vocabulario","title":"O professor GPT","description":"Quando lidamos com novas tecnologias, \xe9 importante come\xe7ar com defini\xe7\xf5es b\xe1sicas que servem como o alicerce para o restante da jornada. No caso do ChatGPT, tr\xeas termos s\xe3o essenciais: ChatGPT, Prompt e LLM (Large Language Models).","sidebar":"ONDG1"},"mestre/arte-ou-engenharia":{"id":"mestre/arte-ou-engenharia","title":"Arte ou engenharia?","description":"Algumas pessoas dizem que criar bons prompts \xe9 uma arte, que requer sensibilidade para as nuances da linguagem e uma intui\xe7\xe3o apurada para prever o impacto das palavras. Outros veem esse processo como engenharia, onde cada detalhe \xe9 ajustado cuidadosamente para alcan\xe7ar o melhor resultado. H\xe1 ainda quem encare como um exerc\xedcio de tentativa e erro, em que cada falha ajuda a refinar a abordagem."},"vamos_esclarecer":{"id":"vamos_esclarecer","title":"Vamos esclarecer?","description":"\xc9 poss\xedvel que este cap\xedtulo do guia tenha despertado a sua curiosidade sobre alguns temas. Para que voc\xea saiba o que ainda vem pela frente neste guia, aqui est\xe3o algumas perguntas que vamos explorar mais adiante:"}}}}')}}]);